// Parsea el comando y sus argumentos. Todo lo demas se resuelve
// consultando Sheets: aca solo se decide QUE consulta correr.

const s = $json;
const texto = String(s.payload?.texto || '').trim();
const m = texto.match(/^\/(\w+)(?:@\w+)?\s*(.*)$/);
const comando = m ? m[1].toLowerCase() : '';
const args = m ? m[2].trim() : '';

const MAPA = {
  status: 'estado', estado: 'estado',
  categorias: 'categorias', categoria: 'categorias',
  hoy: 'hoy', today: 'hoy',
  week: 'semana', semana: 'semana',
  month: 'mes', mes: 'mes',
  cycle: 'ciclo', ciclo: 'ciclo',
  recent: 'recientes', recientes: 'recientes',
  search: 'buscar', buscar: 'buscar',
  pending: 'pendientes', pendientes: 'pendientes',
  next_payment: 'proximo_pago', proximo_pago: 'proximo_pago',
  configuration: 'configuracion', configuracion: 'configuracion',
  budget: 'presupuesto', presupuesto: 'presupuesto',
  help: 'ayuda', ayuda: 'ayuda',
  start: 'inicio'
};

const accion = MAPA[comando] || 'desconocido';
const limite = /^\d+$/.test(args) ? parseInt(args, 10) : (accion === 'recientes' ? 5 : null);

return [{ json: { ...s, consulta: { accion, args, limite } } }];

// Reune todas las lecturas + calcula ciclo vigente, saldos y dias
// restantes. Es el mismo resolverCiclo de WF4: cualquier cambio en uno
// debe reflejarse en el otro (por ahora duplicado adrede para que WF5
// no dependa de invocar WF4 solo para leer).

const sobre = $('Parsear Comando').first().json;
const ZONA = 'America/Bogota';

const cfg = {};
for (const f of $('Leer Configuracion').all().map(i => i.json)) {
  if (f && f.clave) cfg[String(f.clave).trim()] = String(f.valor ?? '').trim();
}
const categorias = $('Leer Categorias').all().map(i => i.json).filter(c => c && c.categoria_id);
const transacciones = $('Leer Transacciones').all().map(i => i.json).filter(t => t && t.transaccion_id);
const ingresos = $('Leer Ingresos').all().map(i => i.json).filter(x => x && x.ingreso_id);
const fijos = $('Leer GastosFijos').all().map(i => i.json).filter(x => x && x.fijo_id);
const pendientes = $('Leer Pendientes').all().map(i => i.json).filter(x => x && x.pendiente_id);

function fronterasDelMes(dt, dias) {
  const ultimo = dt.daysInMonth;
  const set = new Set(dias.map(d => Math.min(d, ultimo)));
  return [...set].sort((a, b) => a - b).map(d => dt.set({ day: d }).startOf('day'));
}
function resolverCiclo(fechaISO, diasInicio) {
  const f = DateTime.fromISO(fechaISO, { zone: ZONA }).startOf('day');
  const todas = [
    ...fronterasDelMes(f.minus({ months: 1 }), diasInicio),
    ...fronterasDelMes(f, diasInicio),
    ...fronterasDelMes(f.plus({ months: 1 }), diasInicio)
  ].sort((a, b) => a.toMillis() - b.toMillis());
  let inicio = null, fin = null;
  for (let i = 0; i < todas.length; i++) {
    if (todas[i] <= f && (i + 1 >= todas.length || todas[i + 1] > f)) {
      inicio = todas[i];
      fin = (i + 1 < todas.length) ? todas[i + 1].minus({ days: 1 }) : todas[i].endOf('month');
      break;
    }
  }
  if (!inicio) { inicio = todas[0]; fin = todas[1] ? todas[1].minus({ days: 1 }) : inicio.endOf('month'); }
  const delMes = fronterasDelMes(inicio, diasInicio);
  const idx = delMes.findIndex(d => d.toISODate() === inicio.toISODate());
  const letra = String.fromCharCode(65 + (idx >= 0 ? idx : 0));
  return { ciclo_id: `${inicio.toFormat('yyyy-LL')}-${letra}`, inicio: inicio.toISODate(), fin: fin.toISODate() };
}

const diasInicio = (cfg.ciclo_dias_inicio || '1,16').split(',').map(s => parseInt(s.trim(), 10)).filter(Number.isFinite);
const hoy = DateTime.now().setZone(ZONA).startOf('day');
const ciclo = resolverCiclo(hoy.toISODate(), diasInicio);
const finCiclo = DateTime.fromISO(ciclo.fin, { zone: ZONA });
const diasRestantes = Math.max(1, Math.floor(finCiclo.diff(hoy, 'days').days) + 1);

function netoCategoria(catId) {
  let gasto = 0, reembolso = 0;
  for (const t of transacciones) {
    if (String(t.estado).trim() !== 'activo') continue;
    if (String(t.ciclo_id).trim() !== ciclo.ciclo_id) continue;
    if (String(t.categoria_id).trim() !== catId) continue;
    const m = Number(t.monto) || 0;
    if (t.tipo === 'gasto' || t.tipo === 'ajuste') gasto += m;
    else if (t.tipo === 'reembolso') reembolso += m;
  }
  return gasto - reembolso;
}

const umbral1 = parseFloat(cfg.umbral_aviso_1 || '70');
const umbral2 = parseFloat(cfg.umbral_aviso_2 || '85');
const umbralCrit = parseFloat(cfg.umbral_critico || '100');

let presupuestoTotal = 0, gastadoTotal = 0;
const catsCalc = [];
for (const c of categorias) {
  const activa = String(c.activa).toUpperCase() === 'TRUE';
  const presupuesto = Number(c.presupuesto) || 0;
  const gastado = netoCategoria(String(c.categoria_id).trim());
  if (activa) { presupuestoTotal += presupuesto; gastadoTotal += gastado; }
  const pct = presupuesto === 0 ? null : Math.round((gastado / presupuesto) * 1000) / 10;
  let estado = 'ok';
  if (presupuesto === 0) estado = 'sin_presupuesto';
  else if (pct > umbralCrit) estado = 'excedido';
  else if (pct >= umbralCrit) estado = 'limite';
  else if (pct >= umbral2) estado = 'alto';
  else if (pct >= umbral1) estado = 'aviso';
  catsCalc.push({ ...c, gastado, disponible: presupuesto - gastado, pct, estado, activa });
}

const disponibleGlobal = presupuestoTotal - gastadoTotal;
const pctGlobal = presupuestoTotal === 0 ? 0 : Math.round((gastadoTotal / presupuestoTotal) * 1000) / 10;
const maximoDiario = Math.round(Math.max(disponibleGlobal, 0) / Math.max(diasRestantes, 1));

// Proximo ingreso pendiente mas cercano.
const pendientesIngreso = ingresos
  .filter(i => String(i.estado).trim() !== 'recibido')
  .map(i => ({ ...i, _fecha: DateTime.fromISO(String(i.proxima_fecha || ''), { zone: ZONA }) }))
  .filter(i => i._fecha.isValid)
  .sort((a, b) => a._fecha.toMillis() - b._fecha.toMillis());
const proximoIngreso = pendientesIngreso[0] || null;

// Fijos del ciclo vigente y cuales ya se registraron (por nombre+monto aprox).
const letraCiclo = ciclo.ciclo_id.slice(-1);
const fijosCiclo = fijos.filter(f => String(f.ciclo).trim() === letraCiclo && String(f.activo).toUpperCase() === 'TRUE');
const fijosPendientes = fijosCiclo.filter(f => {
  const yaPagado = transacciones.some(t =>
    String(t.estado).trim() === 'activo' &&
    String(t.ciclo_id).trim() === ciclo.ciclo_id &&
    String(t.categoria_id).trim() === String(f.categoria_id).trim() &&
    Math.abs(Number(t.monto) - Number(f.monto)) < 1000
  );
  return !yaPagado;
});

const hoyISO = hoy.toISODate();
const semanaInicio = hoy.minus({ days: hoy.weekday - 1 }).toISODate();
const mesInicio = hoy.startOf('month').toISODate();

function sumaGastos(filtroFecha) {
  return transacciones
    .filter(t => String(t.estado).trim() === 'activo' && t.tipo === 'gasto' && filtroFecha(String(t.fecha_movimiento)))
    .reduce((a, t) => a + (Number(t.monto) || 0), 0);
}

return [{
  json: {
    ...sobre,
    cfg, categorias: catsCalc, transacciones, ingresos, fijos, pendientes,
    ciclo, dias_restantes: diasRestantes, hoy: hoyISO,
    saldos: { presupuesto: presupuestoTotal, gastado: gastadoTotal, disponible: disponibleGlobal, porcentaje: pctGlobal, maximo_diario: maximoDiario },
    proximo_ingreso: proximoIngreso,
    fijos_ciclo: fijosCiclo, fijos_pendientes: fijosPendientes,
    gasto_hoy: sumaGastos(f => f === hoyISO),
    gasto_semana: sumaGastos(f => f >= semanaInicio),
    gasto_mes: sumaGastos(f => f >= mesInicio)
  }
}];

const s = $json; const fmt = v => '$' + Math.round(Number(v) || 0).toLocaleString('es-CO');
const g = s.saldos;
const criticas = s.categorias.filter(c => ['alto', 'limite', 'excedido'].includes(c.estado)).sort((a, b) => (b.pct || 0) - (a.pct || 0));

const L = [
  '📊 Estado del ciclo',
  '',
  `Presupuesto: ${fmt(g.presupuesto)}`,
  `Gastado: ${fmt(g.gastado)} (${g.porcentaje}%)`,
  `Disponible: ${fmt(g.disponible)}`,
  `Faltan ${s.dias_restantes} días para el próximo ingreso`
];
if (s.proximo_ingreso) {
  const dias = Math.ceil(DateTime.fromISO(s.proximo_ingreso.proxima_fecha, { zone: 'America/Bogota' }).diff(DateTime.now().setZone('America/Bogota').startOf('day'), 'days').days);
  L.push(`Próximo ingreso: ${s.proximo_ingreso.nombre} en ${dias} días`);
}
if (criticas.length) {
  L.push('', 'Categorías críticas:');
  for (const c of criticas.slice(0, 5)) {
    const icono = c.estado === 'excedido' ? '🚨' : c.estado === 'limite' ? '🔴' : '🟠';
    L.push(`${icono} ${c.nombre}: ${c.pct}%`);
  }
}
if (s.fijos_pendientes?.length) {
  L.push('', `Fijos pendientes este ciclo: ${s.fijos_pendientes.map(f => f.concepto).join(', ')}`);
}
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: L.join('\n') } }];

const s = $json; const fmt = v => '$' + Math.round(Number(v) || 0).toLocaleString('es-CO');
const ICONO = { ok: '', aviso: ' 🟡', alto: ' 🟠', limite: ' 🔴', excedido: ' 🚨', sin_presupuesto: ' ℹ️' };
const activas = s.categorias.filter(c => c.activa).sort((a, b) => (b.pct || 0) - (a.pct || 0));
const L = ['📂 Categorías del ciclo', ''];
for (const c of activas) {
  const linea = c.presupuesto > 0
    ? `${c.nombre}: ${fmt(c.gastado)} / ${fmt(c.presupuesto)} — ${c.pct}%${ICONO[c.estado] || ''}`
    : `${c.nombre}: ${fmt(c.gastado)} (sin presupuesto)${ICONO.sin_presupuesto}`;
  L.push(linea);
}
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: L.join('\n') } }];

const s = $json; const fmt = v => '$' + Math.round(Number(v) || 0).toLocaleString('es-CO');
const hoyTx = s.transacciones.filter(t => String(t.estado).trim() === 'activo' && t.tipo === 'gasto' && String(t.fecha_movimiento) === s.hoy);
const L = [`📅 Hoy: ${fmt(s.gasto_hoy)}`, ''];
if (hoyTx.length === 0) L.push('Sin gastos registrados hoy.');
else for (const t of hoyTx) L.push(`• ${fmt(t.monto)} — ${t.categoria || t.categoria_id}${t.descripcion ? ' (' + t.descripcion + ')' : ''}`);
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: L.join('\n') } }];

const s = $json; const fmt = v => '$' + Math.round(Number(v) || 0).toLocaleString('es-CO');
const L = [`📆 Esta semana: ${fmt(s.gasto_semana)}`, `Disponible del ciclo: ${fmt(s.saldos.disponible)}`];
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: L.join('\n') } }];

const s = $json; const fmt = v => '$' + Math.round(Number(v) || 0).toLocaleString('es-CO');
const L = [`🗓️ Este mes: ${fmt(s.gasto_mes)}`];
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: L.join('\n') } }];

const s = $json; const fmt = v => '$' + Math.round(Number(v) || 0).toLocaleString('es-CO');
const n = s.consulta.limite || 5;
const recientes = s.transacciones.filter(t => String(t.estado).trim() === 'activo').sort((a, b) => new Date(b.timestamp_registro) - new Date(a.timestamp_registro)).slice(0, n);
const L = [`🧾 Últimos ${recientes.length} movimientos`, ''];
for (const t of recientes) {
  const idCorto = String(t.transaccion_id).split('-').pop();
  L.push(`${idCorto} · ${fmt(t.monto)} — ${t.categoria || t.categoria_id} · ${t.fecha_movimiento}`);
}
if (recientes.length) L.push('', 'Usa /corregir <id> o /anular <id> con el código de arriba.');
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: L.join('\n') } }];

const s = $json; const fmt = v => '$' + Math.round(Number(v) || 0).toLocaleString('es-CO');
const q = String(s.consulta.args || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
if (!q) return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: 'Usa /buscar <texto>, por ejemplo /buscar electrohuila' } }];
const norm = x => String(x || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const r = s.transacciones.filter(t => String(t.estado).trim() === 'activo' && (norm(t.comercio_proveedor).includes(q) || norm(t.descripcion).includes(q) || norm(t.categoria).includes(q)));
const total = r.reduce((a, t) => a + (Number(t.monto) || 0), 0);
const L = [`🔎 "${s.consulta.args}" — ${r.length} resultado(s), total ${fmt(total)}`, ''];
for (const t of r.slice(0, 10)) L.push(`${fmt(t.monto)} — ${t.categoria || t.categoria_id} · ${t.fecha_movimiento}${t.comercio_proveedor ? ' · ' + t.comercio_proveedor : ''}`);
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: L.join('\n') } }];

const s = $json;
const abiertos = s.pendientes.filter(p => String(p.estado).trim() === 'abierto');
const L = [`⏳ Pendientes abiertos: ${abiertos.length}`, ''];
for (const p of abiertos) L.push(`${p.pendiente_id} — ${p.estado_maquina} (expira ${p.fecha_expiracion?.slice(11, 16) || ''})`);
if (!abiertos.length) L.push('No tienes confirmaciones pendientes.');
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: L.join('\n') } }];

const s = $json; const fmt = v => '$' + Math.round(Number(v) || 0).toLocaleString('es-CO');
const ZONA = 'America/Bogota';
if (!s.proximo_ingreso) return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: 'No hay ingresos pendientes configurados.' } }];
const dias = Math.ceil(DateTime.fromISO(s.proximo_ingreso.proxima_fecha, { zone: ZONA }).diff(DateTime.now().setZone(ZONA).startOf('day'), 'days').days);
const L = [
  `💰 Próximo ingreso`,
  '',
  `${s.proximo_ingreso.nombre}`,
  `Monto esperado: ${fmt(s.proximo_ingreso.monto_esperado)}`,
  `Fecha: ${s.proximo_ingreso.proxima_fecha}`,
  `Faltan ${dias} días`
];
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: L.join('\n') } }];

const s = $json; const fmt = v => '$' + Math.round(Number(v) || 0).toLocaleString('es-CO');
const activas = s.categorias.filter(c => c.activa);
const L = ['💵 Presupuestos por categoría', ''];
for (const c of activas) L.push(`${c.nombre}: ${fmt(c.presupuesto)}`);
L.push('', `Total: ${fmt(s.saldos.presupuesto)}`);
L.push('', 'Para cambiar un presupuesto, editalo directamente en la hoja Categorias.');
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: L.join('\n') } }];

const s = $json;
if (!s.ctx.es_admin) return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: 'Solo el administrador puede ver la configuración.' } }];
const L = ['⚙️ Configuración', ''];
const claves = ['ciclo_dias_inicio', 'umbral_aviso_1', 'umbral_aviso_2', 'umbral_critico', 'confirmacion_activa', 'resumen_semanal_activo', 'resumen_diario_activo', 'confianza_minima_ia'];
for (const k of claves) L.push(`${k}: ${s.cfg[k] ?? ''}`);
return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: L.join('\n') } }];

// Traduce el formato {inline_keyboard:[[{text,callback_data}]]}
// (el que arman los Code nodes previos) al formato que espera
// el nodo nativo Telegram: rows[].row.buttons[].additionalFields.
const s = $json;
let filas = [];
if (s.teclado) {
  let ik;
  try { ik = JSON.parse(s.teclado).inline_keyboard; } catch (e) { ik = []; }
  filas = ik.map(fila => ({ row: { buttons: fila.map(b => ({ text: b.text, additionalFields: { callback_data: b.callback_data } })) } }));
}
return [{ json: { ...s, _filas_botones: filas, _con_botones: filas.length > 0 } }];
